// Possible values left in `h_errno'.
const (
	HOST_NOT_FOUND = 1
	// Non-Authoritative Host not found,
	// or SERVERFAIL.
	TRY_AGAIN = 2
)

// Non recoverable errors, FORMERR, REFUSED,
// NOTIMP.
const NO_RECOVERY = 3

// Valid name, no data record of requested
// type.
const NO_DATA = 4

const (
	// See errno.
	NETDB_INTERNAL = -1
	// No problem.
	NETDB_SUCCESS = 0
	// No address, look for MX record.
	NO_ADDRESS = 4
)

// Possible values for `ai_flags' field in `addrinfo' structure.
const (
	AI_PASSIVE = 1
	// Request for canonical name.
	AI_CANONNAME = 2
	// Don't use name resolution.
	AI_NUMERICHOST = 4
	// IPv4 mapped addresses are acceptable.
	AI_V4MAPPED = 8
	// Return IPv4 mapped and IPv6 addresses.
	AI_ALL = 16
	// Use configuration of this host to choose
	// returned address type..
	AI_ADDRCONFIG = 32
)

// Don't use name resolution.
const AI_NUMERICSERV = 1024

// Error values for `getaddrinfo' function.
const (
	EAI_BADFLAGS = -1
	// NAME or SERVICE is unknown.
	EAI_NONAME = -2
	// Temporary failure in name resolution.
	EAI_AGAIN = -3
	// Non-recoverable failure in name res.
	EAI_FAIL = -4
	// `ai_family' not supported.
	EAI_FAMILY = -6
	// `ai_socktype' not supported.
	EAI_SOCKTYPE = -7
	// SERVICE not supported for `ai_socktype'.
	EAI_SERVICE = -8
	// Memory allocation failure.
	EAI_MEMORY = -10
	// System error returned in `errno'.
	EAI_SYSTEM = -11
	// Argument buffer overflow.
	EAI_OVERFLOW = -12
)

const (
	NI_MAXHOST = 1025
	NI_MAXSERV = 32
)

const (
	// Don't try to look up hostname.
	NI_NUMERICHOST = 1
	// Don't convert port number to name.
	NI_NUMERICSERV = 2
	// Only return nodename portion.
	NI_NOFQDN = 4
	// Don't return numeric addresses.
	NI_NAMEREQD = 8
	// Look up UDP service rather than TCP.
	NI_DGRAM = 16
)

